import{_ as t,c as o,o as a,ae as n}from"./chunks/framework.CDjunVez.js";const g=JSON.parse('{"title":"Preparing for Generator","description":"","frontmatter":{},"headers":[],"relativePath":"manual/generator_preparation.md","filePath":"manual/generator_preparation.md"}'),l={name:"manual/generator_preparation.md"};function d(i,e,s,c,r,u){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="preparing-for-generator" tabindex="-1">Preparing for Generator <a class="header-anchor" href="#preparing-for-generator" aria-label="Permalink to &quot;Preparing for Generator&quot;">​</a></h1><p>The Extended Note Block possesses many custom NBT tags that allow for richer musical effects compared to traditional note blocks. This is particularly useful for generating note blocks in bulk via command blocks or external generators.</p><h2 id="nbt-structure-overview" tabindex="-1">NBT Structure Overview <a class="header-anchor" href="#nbt-structure-overview" aria-label="Permalink to &quot;NBT Structure Overview&quot;">​</a></h2><p>The NBT data of the Extended Note Block is primarily divided into <strong>Basic Attributes</strong> and <strong>Advanced Data (AdvancedData)</strong>.</p><h3 id="basic-attributes-root" tabindex="-1">Basic Attributes (Root) <a class="header-anchor" href="#basic-attributes-root" aria-label="Permalink to &quot;Basic Attributes (Root)&quot;">​</a></h3><p>These attributes are located directly under the root node of the NBT:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Tag Name</th><th style="text-align:left;">Type</th><th style="text-align:left;">Description</th><th style="text-align:left;">Range/Unit</th><th style="text-align:left;">Default</th></tr></thead><tbody><tr><td style="text-align:left;"><code>note</code></td><td style="text-align:left;">Int</td><td style="text-align:left;">MIDI Pitch</td><td style="text-align:left;">0-127 (60 is Middle C)</td><td style="text-align:left;">60</td></tr><tr><td style="text-align:left;"><code>velocity</code></td><td style="text-align:left;">Int</td><td style="text-align:left;">MIDI Velocity (Base Volume)</td><td style="text-align:left;">0-127</td><td style="text-align:left;">100</td></tr><tr><td style="text-align:left;"><code>sustainTime</code></td><td style="text-align:left;">Int</td><td style="text-align:left;">Note Sustain Time</td><td style="text-align:left;">Ticks (20 ticks = 1s)</td><td style="text-align:left;">40</td></tr><tr><td style="text-align:left;"><code>delayedPlayingTime</code></td><td style="text-align:left;">Int</td><td style="text-align:left;">Delay Time</td><td style="text-align:left;">Milliseconds (ms)</td><td style="text-align:left;">0</td></tr><tr><td style="text-align:left;"><code>fadeInTime</code></td><td style="text-align:left;">Int</td><td style="text-align:left;">Fade In Time</td><td style="text-align:left;">Ticks</td><td style="text-align:left;">0</td></tr><tr><td style="text-align:left;"><code>fadeOutTime</code></td><td style="text-align:left;">Int</td><td style="text-align:left;">Fade Out Time</td><td style="text-align:left;">Ticks</td><td style="text-align:left;">0</td></tr></tbody></table><h3 id="block-states" tabindex="-1">Block States <a class="header-anchor" href="#block-states" aria-label="Permalink to &quot;Block States&quot;">​</a></h3><p>In addition to NBT data, the Extended Note Block uses BlockStates to handle Redstone signals and visual representation.</p><table tabindex="0"><thead><tr><th style="text-align:left;">State Name</th><th style="text-align:left;">Type</th><th style="text-align:left;">Values</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:left;"><code>pitch</code></td><td style="text-align:left;">Enum</td><td style="text-align:left;"><code>c</code>, <code>cs</code>, <code>d</code>, <code>ds</code>, <code>e</code>, <code>f</code>, <code>fs</code>, <code>g</code>, <code>gs</code>, <code>a</code>, <code>as</code>, <code>b</code></td><td style="text-align:left;">Corresponds to the pitch of the current note within an octave (Note % 12). Primarily used for resource packs to change block textures. For example, <code>cs</code> stands for C#.</td></tr><tr><td style="text-align:left;"><code>powered</code></td><td style="text-align:left;">Boolean</td><td style="text-align:left;"><code>true</code>, <code>false</code></td><td style="text-align:left;">Marks whether the block is activated by a Redstone signal. Used for detecting signal edges (rising/falling edge).</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Note</p><p>When placing blocks using <code>setblock</code>, you usually do not need to manually specify <code>pitch</code>. When the block is activated by Redstone, it will automatically calculate and update this state based on the <code>note</code> value in the NBT.</p></div><h3 id="advanced-data-advanceddata-compound" tabindex="-1">Advanced Data (<code>AdvancedData</code> Compound) <a class="header-anchor" href="#advanced-data-advanceddata-compound" aria-label="Permalink to &quot;Advanced Data (`AdvancedData` Compound)&quot;">​</a></h3><p>All advanced feature data is stored within a compound tag named <code>AdvancedData</code>. Generators need to construct precise List data structures.</p><h4 id="_1-pitch-bend-points-pitchbendpoints" tabindex="-1">1. Pitch Bend Points (<code>PitchBendPoints</code>) <a class="header-anchor" href="#_1-pitch-bend-points-pitchbendpoints" aria-label="Permalink to &quot;1. Pitch Bend Points (`PitchBendPoints`)&quot;">​</a></h4><ul><li><strong>Type</strong>: <code>List&lt;Compound&gt;</code></li><li><strong>Element Structure</strong>: <code>{t: &lt;float&gt;, v: &lt;float&gt;}</code><ul><li><code>t</code> (Time): Time point, ranging from <code>0.0</code> (start) to <code>1.0</code> (end).</li><li><code>v</code> (Value): <strong>Semitones</strong> offset. <ul><li><code>0.0</code>: No offset (original pitch).</li><li><code>12.0</code>: One octave up.</li><li><code>-12.0</code>: One octave down.</li><li>Decimals are supported, e.g., <code>0.5</code> semitones (50 cents).</li></ul></li></ul></li><li><strong>Interpolation Behavior</strong>: The game performs <strong>linear interpolation</strong> between two key points.</li></ul><h4 id="_2-volume-points-volumepoints" tabindex="-1">2. Volume Points (<code>VolumePoints</code>) <a class="header-anchor" href="#_2-volume-points-volumepoints" aria-label="Permalink to &quot;2. Volume Points (`VolumePoints`)&quot;">​</a></h4><ul><li><strong>Type</strong>: <code>List&lt;Compound&gt;</code></li><li><strong>Element Structure</strong>: <code>{t: &lt;float&gt;, v: &lt;float&gt;}</code><ul><li><code>t</code> (Time): Time point, ranging from <code>0.0</code> to <code>1.0</code>.</li><li><code>v</code> (Value): <strong>Volume Multiplier</strong>. <ul><li><code>1.0</code>: Standard volume (determined by <code>velocity</code>).</li><li><code>0.0</code>: Mute.</li><li><code>2.0</code>: Double the standard volume.</li></ul></li></ul></li><li><strong>Interpolation Behavior</strong>: The game performs <strong>linear interpolation</strong> between two key points.</li><li><strong>Override Rule</strong>: Once this list is non-empty, <code>fadeInTime</code>/<code>fadeOutTime</code> in the NBT root node will be ignored.</li></ul><h4 id="_3-sound-path-soundpath" tabindex="-1">3. Sound Path (<code>SoundPath</code>) <a class="header-anchor" href="#_3-sound-path-soundpath" aria-label="Permalink to &quot;3. Sound Path (`SoundPath`)&quot;">​</a></h4><ul><li><strong>Type</strong>: <code>List&lt;Compound&gt;</code></li><li><strong>Element Structure</strong>: <code>{x: &lt;double&gt;, y: &lt;double&gt;, z: &lt;double&gt;}</code><ul><li>These coordinates are <strong>offsets relative to the center of the note block</strong>. For example, <code>{x:0, y:1, z:0}</code> indicates a position 1 block above the note block.</li></ul></li><li><strong>Sampling Behavior</strong>: Unlike curves, <code>SoundPath</code> <strong>does NOT perform linear interpolation</strong>. <ul><li>The game calculates the index <code>Index = Progress * (Size - 1)</code> based on the current playback progress and directly takes the position of the corresponding point.</li><li><strong>Recommendation</strong>: If smooth movement is required, the generator should generate sufficiently dense points (e.g., if <code>sustainTime</code> is 40 ticks, it is recommended to generate 40 path points, one per tick).</li></ul></li></ul><h4 id="_4-gui-expression-cache-expressionx-y-z" tabindex="-1">4. GUI Expression Cache (<code>ExpressionX</code>/<code>Y</code>/<code>Z</code>) <a class="header-anchor" href="#_4-gui-expression-cache-expressionx-y-z" aria-label="Permalink to &quot;4. GUI Expression Cache (`ExpressionX`/`Y`/`Z`)&quot;">​</a></h4><ul><li><strong>Type</strong>: <code>String</code></li><li>These are merely strings used to echo user-input formulas (like <code>sin(t * pi)</code>) in the GUI.</li></ul><div class="warning custom-block"><p class="custom-block-title">Important</p><p>The game core logic <strong>completely ignores</strong> these strings. If you are an external generator, you <strong>do not need</strong> to generate these strings unless you want the player to see specific formulas when opening the GUI. What you need to generate is the <code>SoundPath</code> list above.</p></div><h2 id="setblock-command-examples" tabindex="-1">Setblock Command Examples <a class="header-anchor" href="#setblock-command-examples" aria-label="Permalink to &quot;Setblock Command Examples&quot;">​</a></h2><p>You can use the <code>/setblock</code> command to place an Extended Note Block with preset NBT data.</p><p><strong>Basic Example:</strong></p><div class="language-mcfunction vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mcfunction</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>setblock ~ ~1 ~ extendednoteblock:extended_note_block{note:64, velocity:120, sustainTime:10}</span></span></code></pre></div><p><strong>Advanced Example (including pitch bend):</strong></p><div class="language-mcfunction vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mcfunction</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>setblock ~ ~1 ~ extendednoteblock:extended_note_block{note:60, sustainTime:40, AdvancedData:{PitchBendPoints:[{t:0.0f, v:0.0f}, {t:1.0f, v:12.0f}]}}</span></span></code></pre></div><h2 id="important-notes" tabindex="-1">Important Notes <a class="header-anchor" href="#important-notes" aria-label="Permalink to &quot;Important Notes&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">Relationship between SoundPath and Expression</p><p>In <code>AdvancedData</code>, you might find both <code>SoundPath</code> and <code>ExpressionX/Y/Z</code> existing simultaneously.</p><ul><li><strong>Expr (Expression)</strong>: Used only for <strong>GUI display and editing</strong>. The game does <strong>not</strong> calculate these expressions at runtime.</li><li><strong>SoundPath</strong>: This is the path data actually used by the game when playing sounds.</li></ul><p><strong>Key Point:</strong> If you are writing a generator, you <strong>must generate the <code>SoundPath</code> list data directly</strong>. Just writing <code>Expression</code> strings is ineffective; the sound will not move unless the player manually opens the GUI and saves, at which point the client calculates the path points based on the expressions and writes them to <code>SoundPath</code>.</p></div><div class="info custom-block"><p class="custom-block-title">Volume Control Priority</p><p>Volume is mainly controlled by the following two attributes:</p><ol><li><strong><code>velocity</code> (Base MIDI Velocity)</strong>: Determines the base volume of the entire note.</li><li><strong><code>VolumePoints</code> (Advanced Volume Curve)</strong>: If a non-empty <code>VolumePoints</code> list exists in <code>AdvancedData</code>, it will <strong>completely override</strong> the effect of the base <code>velocity</code>.</li></ol><p>This means if you want to use dynamic volume envelopes (like ADSR), you should use <code>VolumePoints</code>; for simple fixed volume, use <code>velocity</code>.</p></div>',31)])])}const h=t(l,[["render",d]]);export{g as __pageData,h as default};
